 public class Product {            public string Name { get; set; }            public decimal Price { get; set; }            public string[] Sizes { get; set; }            public DateTime ExpiryDate { get; set; }        }        public static void TestJsonSerializer() {            Console.WriteLine("---------------------------------------------------");            //JsonConvert.DefaultSettings = () => new JsonSerializerSettings {            //    Formatting = Formatting.Indented,            //    TypeNameHandling = TypeNameHandling.Objects,            //    ContractResolver = new CamelCasePropertyNamesContractResolver()            //};            //string jsonData = JsonConvert.SerializeObject(new Point(45, 789));            Product product = new Product {                Name = "Apple",                ExpiryDate = new DateTime(2008, 12, 28),                Price = 3.99M,                Sizes = new string[] { "Small", "Medium", "Large" }            };            string jsonData = JsonConvert.SerializeObject(product);            Console.WriteLine("Product String:{0}", jsonData);            Product pr = JsonConvert.DeserializeObject<Product>(jsonData);            Console.WriteLine("Product:{0}", pr);            string jsonData2 = JsonConvert.SerializeObject(new Point(45, 789));            Console.WriteLine("Point String:{0}", jsonData2);            Point po = JsonConvert.DeserializeObject<Point>(jsonData2);            Console.WriteLine("Point:{0}", po);            string jsonData3 = JsonConvert.SerializeObject(new Size(1024, 768));            Console.WriteLine("Size String:{0}", jsonData3);            Size si = JsonConvert.DeserializeObject<Size>(jsonData3);            Console.WriteLine("Size:{0}", si);            Font fo = new Font("Segoe UI", 9, FontStyle.Bold);            string jsonData4 = JsonConvert.SerializeObject(fo);            Console.WriteLine("Font String:{0}", jsonData4);            Font fo2 = JsonConvert.DeserializeObject<Font>(jsonData4);            Console.WriteLine("Font:{0}", fo2);            Console.WriteLine("---------------------------------------------------");            //---------------------------------------------------            //Product String: { "Name":"Apple","Price":3.99,"Sizes":["Small","Medium","Large"],"ExpiryDate":"2008-12-28T00:00:00"}            //Product: LessonEditor.objects.TestClass + Product            //Point String:"45, 789"            //Point: { X = 45,Y = 789}            //Size String:"1024, 768"            //Size: { Width = 1024, Height = 768}            //---------------------------------------------------        }